using System.Reflection;using System.Runtime.CompilerServices;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using DeskCanvas.Core;
namespace DeskCanvas.App.Windows;
internal static class V30ClockUi{[ModuleInitializer]internal static void Init(){EventManager.RegisterClassHandler(typeof(MediaWindow),FrameworkElement.LoadedEvent,new RoutedEventHandler(MediaLoaded));EventManager.RegisterClassHandler(typeof(BuiltInContentPicker),FrameworkElement.LoadedEvent,new RoutedEventHandler(PickerLoaded));EventManager.RegisterClassHandler(typeof(MainWindow),FrameworkElement.LoadedEvent,new RoutedEventHandler(MainLoaded));}private static void MediaLoaded(object s,RoutedEventArgs e){if(s is MediaWindow w){w.ApplyTextClock();w.SizeChanged+=(_,__)=>w.ApplyTextClock();}}private static void MainLoaded(object s,RoutedEventArgs e){if(s is MainWindow w)w.AddClockTextEditor();}private static void PickerLoaded(object s,RoutedEventArgs e){if(s is not BuiltInContentPicker p)return;var f=p.GetType();var preview=(CanvasItem?)f.GetField("previewItem",BindingFlags.Instance|BindingFlags.NonPublic)?.GetValue(p);var options=(StackPanel?)f.GetField("options",BindingFlags.Instance|BindingFlags.NonPublic)?.GetValue(p);if(preview is null||options is null||options.Tag is string)return;options.Tag="v30-clock";var check=new CheckBox{Content="背景なし・文字だけ"};var font=new TextBox{ToolTip="フォント名"};var color=new TextBox{ToolTip="文字色 (#RRGGBB)"};var weight=new ComboBox{ItemsSource=Enum.GetValues<ClockFontWeight>()};void Apply(){preview.Clock.Backgroundless=check.IsChecked==true;preview.Clock.FontFamily=font.Text;preview.Clock.TextColor=color.Text;preview.Clock.FontWeight=weight.SelectedItem is ClockFontWeight v?v:ClockFontWeight.Regular;}check.Checked+=(_,__)=>Apply();check.Unchecked+=(_,__)=>Apply();font.LostFocus+=(_,__)=>Apply();color.LostFocus+=(_,__)=>Apply();weight.SelectionChanged+=(_,__)=>Apply();options.Children.Add(new TextBlock{Text="文字時計",Margin=new Thickness(0,12,0,2)});options.Children.Add(check);options.Children.Add(font);options.Children.Add(color);options.Children.Add(weight);}}
partial class MediaWindow{internal void ApplyTextClock(){if(item.ContentKind!=CanvasContentKinds.Clock||!item.Clock.Backgroundless||content.View is not Border card)return;card.Effect=null;card.Background=Brushes.Transparent;card.BorderThickness=new Thickness(0);card.Padding=new Thickness(0);card.CornerRadius=new CornerRadius(0);foreach(var text in card.Descendants().OfType<TextBlock>()){text.Foreground=ClockTextStyle.Foreground(item.Clock.TextColor,text.Foreground);text.FontFamily=ClockTextStyle.Family(item.Clock.FontFamily);text.FontWeight=ClockTextStyle.Weight(item.Clock.FontWeight);}ItemContent.RenderTransformOrigin=new Point(.5,.5);ItemContent.LayoutTransform=new ScaleTransform(Math.Clamp(item.Width/300d,.32,4),Math.Clamp(item.Height/150d,.32,4));}}
internal static class ClockTextStyle{internal static FontFamily Family(string value){try{return string.IsNullOrWhiteSpace(value)?SystemFonts.MessageFontFamily:new FontFamily(value);}catch{return SystemFonts.MessageFontFamily;}}internal static Brush Foreground(string value,Brush fallback){try{return string.IsNullOrWhiteSpace(value)?fallback:new SolidColorBrush((Color)ColorConverter.ConvertFromString(value));}catch{return fallback;}}internal static FontWeight Weight(ClockFontWeight v)=>v switch{ClockFontWeight.Light=>FontWeights.Light,ClockFontWeight.SemiBold=>FontWeights.SemiBold,ClockFontWeight.Bold=>FontWeights.Bold,ClockFontWeight.Black=>FontWeights.Black,_=>FontWeights.Regular};}
partial class MainWindow{private CheckBox? textClockCheck;private TextBox? textClockFont,textClockColor;private ComboBox? textClockWeight;internal void AddClockTextEditor(){if(textClockCheck is not null)return;textClockCheck=new CheckBox{Content="背景なし・文字だけ",Margin=new Thickness(0,12,0,3)};textClockFont=new TextBox{ToolTip="フォント名"};textClockColor=new TextBox{ToolTip="文字色 (#RRGGBB)"};textClockWeight=new ComboBox{ItemsSource=Enum.GetValues<ClockFontWeight>()};foreach(var c in new Control[]{textClockCheck,textClockFont,textClockColor,textClockWeight}){if(c is CheckBox q){q.Checked+=ClockChanged;q.Unchecked+=ClockChanged;}else if(c is TextBox t)t.LostFocus+=ClockChanged;else if(c is ComboBox z)z.SelectionChanged+=ClockChanged;}EditorPanel.Children.Add(new TextBlock{Text="文字時計",Margin=new Thickness(0,12,0,3)});EditorPanel.Children.Add(textClockCheck);EditorPanel.Children.Add(textClockFont);EditorPanel.Children.Add(textClockColor);EditorPanel.Children.Add(textClockWeight);ItemsList.SelectionChanged+=(_,__)=>RefreshTextClockEditor();}private void RefreshTextClockEditor(){if(textClockCheck is null)return;var visible=SelectedItem?.ContentKind==CanvasContentKinds.Clock;textClockCheck.Visibility=Visibility.Visible;if(!visible)return;var c=SelectedItem!.Clock;textClockCheck.IsChecked=c.Backgroundless;textClockFont!.Text=c.FontFamily;textClockColor!.Text=c.TextColor;textClockWeight!.SelectedItem=c.FontWeight;}private void ClockChanged(object? s,RoutedEventArgs e)=>SaveTextClock();private void ClockChanged(object? s,EventArgs e)=>SaveTextClock();private void SaveTextClock(){if(SelectedItem is not {ContentKind:CanvasContentKinds.Clock} item||textClockCheck is null)return;item.Clock.Backgroundless=textClockCheck.IsChecked==true;item.Clock.FontFamily=textClockFont?.Text??"";item.Clock.TextColor=textClockColor?.Text??"";item.Clock.FontWeight=textClockWeight?.SelectedItem is ClockFontWeight w?w:ClockFontWeight.Regular;controller.GetType().GetMethod("SetTheme",BindingFlags.Instance|BindingFlags.NonPublic)?.Invoke(controller,[item,item.Theme]);}}
